-- nexo.social — coleção embutida dos itens exclusivos (gerado a partir de
-- public/colecao/<tema>/<fundos|adesivos|bottons>). Os arquivos ficam no
-- próprio site; o catálogo e as concessões, no banco (db/exclusivos.sql).
-- O superadministrador monta o kit e envia em /admin → Exclusivos.
-- Pode rodar mais de uma vez: atualiza nome, tema e edição sem mexer em quem já recebeu.

ON CONFLICT (image_path) DO UPDATE SET
  title = EXCLUDED.title,
  kind = EXCLUDED.kind,
  collection = EXCLUDED.collection,
  edition = EXCLUDED.edition,
  thumb_path = EXCLUDED.thumb_path,
  sort_order = EXCLUDED.sort_order;
